// Test script to verify credentials are still valid
// Only outputs pass/fail status, not sensitive values

const https = require('https');

require('dotenv').config({ path: '.env.test' });

let passed = 0;
let failed = 0;

function testResult(name, success) {
  if (success) {
    console.log(`✅ ${name}: VALID`);
    passed++;
  } else {
    console.log(`❌ ${name}: INVALID or unreachable`);
    failed++;
  }
}

async function testDatabase() {
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    testResult('DATABASE_URL', false);
    return;
  }

  try {
    // Extract host from postgres://user:pass@host:port/db
    const match = dbUrl.match(/@([^:]+):(\d+)/);
    if (!match) {
      testResult('DATABASE_URL', false);
      return;
    }

    const host = match[1];
    const port = parseInt(match[2], 10);

    // Simple TCP connection test
    const net = require('net');

    return new Promise((resolve) => {
      const socket = new net.Socket();
      socket.setTimeout(5000);

      socket.on('connect', () => {
        socket.destroy();
        testResult('DATABASE_URL', true);
        resolve();
      });

      socket.on('timeout', () => {
        socket.destroy();
        testResult('DATABASE_URL', false);
        resolve();
      });

      socket.on('error', () => {
        socket.destroy();
        testResult('DATABASE_URL', false);
        resolve();
      });

      socket.connect(port, host);
    });
  } catch (e) {
    testResult('DATABASE_URL', false);
  }
}

function testApiKey(url, keyName, keyHeader, keyValue) {
  return new Promise((resolve) => {
    if (!keyValue) {
      testResult(keyName, false);
      resolve();
      return;
    }

    const urlObj = new URL(url);
    const options = {
      hostname: urlObj.host,
      path: urlObj.pathname,
      method: 'GET',
      headers: {
        [keyHeader]: keyValue,
        'Content-Type': 'application/json'
      },
      timeout: 10000
    };

    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        // Consider 2xx and 401 (auth required but key recognized) as "valid key"
        const validStatus = res.statusCode >= 200 && res.statusCode < 400;
        const recognizedKey = res.statusCode === 401; // API key recognized but unauthorized
        testResult(keyName, validStatus || recognizedKey);
        resolve();
      });
    });

    req.on('error', () => {
      testResult(keyName, false);
      resolve();
    });

    req.on('timeout', () => {
      req.destroy();
      testResult(keyName, false);
      resolve();
    });

    req.end();
  });
}

async function main() {
  console.log('🔍 Testing credentials from .env.test\n');

  await testDatabase();

  // Test AWS credentials (check if keys are format-valid)
  const awsKeyId = process.env.AWS_ACCESS_KEY_ID;
  const awsSecret = process.env.AWS_SECRET_ACCESS_KEY;
  if (awsKeyId && awsKeyId.startsWith('AKIA') && awsKeyId.length === 20) {
    if (awsSecret && awsSecret.length >= 40) {
      testResult('AWS credentials', true);
    } else {
      testResult('AWS credentials', false);
    }
  } else {
    testResult('AWS credentials', false);
  }

  // Test Anthropic API key (make a simple API call)
  await testApiKey(
    'https://api.anthropic.com/v1/models',
    'ANTHROPIC_API_KEY',
    'x-api-key',
    process.env.ANTHROPIC_API_KEY
  );

  // Test Stripe API key (verify key format)
  const stripeKey = process.env.STRIPE_SECRET_KEY;
  if (stripeKey && (stripeKey.startsWith('sk_live_') || stripeKey.startsWith('sk_test_'))) {
    testResult('STRIPE_SECRET_KEY (format)', true);
  } else {
    testResult('STRIPE_SECRET_KEY (format)', false);
  }

  // Test Logfire token (format check)
  const logfireToken = process.env.LOGFIRE_TOKEN;
  if (logfireToken && logfireToken.startsWith('pfl_')) {
    testResult('LOGFIRE_TOKEN (format)', true);
  } else {
    testResult('LOGFIRE_TOKEN (format)', false);
  }

  console.log(`\n📊 Results: ${passed} passed, ${failed} failed`);

  if (failed > 0) {
    process.exit(1);
  }
}

main().catch(console.error);

