// Recommended version with security improvements:

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

const app = express();

// 1. SECURITY: Add security headers
app.use(helmet());

// 2. SECURITY: Prevent request body bloating
app.use(express.json({ limit: '10kb' }));

// 3. SECURITY: Rate limiting to prevent DoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api', limiter);

// 4. ERROR HANDLING: Global error handler
app.use((err, req, res, next) => {
  console.error('Error:', err.message);

  // Don't leak stack traces in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(statusCode).json({ 
    error: message,
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
  });
});

// 5. INPUT VALIDATION: Validate query parameters
const validateUserQuery = [
  body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be 1-100'),
  body('offset').optional().isInt({ min: 0 }).withMessage('Offset must be non-negative'),
];

app.get('/users', validateUserQuery, (req, res, next) => {
  // Check validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // Safe input handling
  const limit = Math.min(parseInt(req.query.limit) || 10, 100);
  const offset = parseInt(req.query.offset) || 0;

  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Safe pagination
  const paginatedUsers = users.slice(offset, offset + limit);

  res.json({ 
    data: paginatedUsers, 
    pagination: { limit, offset, total: users.length } 
  });
});

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// 6. 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

