  message: { error: 'Too many requests, please try again later' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api', limiter);

// Input validation helper
const validateQueryParams = (params, schema) => {
  const errors = [];
  for (const [key, rules] of Object.entries(schema)) {
    const value = params[key];
    if (rules.required && (value === undefined || value === '')) {
      errors.push(`Missing required parameter: ${key}`);
      continue;
    }
    if (value !== undefined) {
      if (rules.type === 'number' && isNaN(Number(value))) {
        errors.push(`Invalid type for ${key}: expected number`);
      }
      if (rules.type === 'string' && typeof value !== 'string') {
        errors.push(`Invalid type for ${key}: expected string`);
      }
      if (rules.maxLength && value.length > rules.maxLength) {
        errors.push(`${key} exceeds maximum length of ${rules.maxLength}`);
      }
      if (rules.pattern && !rules.pattern.test(value)) {
        errors.push(`Invalid format for ${key}`);
      }
    }
  }
  return errors;
};

// Health endpoint with input validation
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint with query parameter validation
app.get('/users', (req, res, next) => {
  // Define validation schema
