    page: { required: false, type: 'number' },
    limit: { required: false, type: 'number' },
    search: { required: false, type: 'string', maxLength: 100 },
  };

  const errors = validateQueryParams(req.query, schema);
  if (errors.length > 0) {
    return res.status(400).json({ error: 'Validation failed', details: errors });
  }

  const { page = 1, limit = 10, search = '' } = req.query;

  // Sanitize and validate numeric params
  const pageNum = Math.max(1, parseInt(page, 10));
  const limitNum = Math.min(100, Math.max(1, parseInt(limit, 10))); // Cap at 100

  // Sample user data (in real app, this would come from DB)
